<!DOCTYPE html>
<html lang="pt">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Auditoria | Gestão de Expedientes</title><link rel="stylesheet" href="assets/css/style.css"></head>
<body class="app-page dashboard-layout">
<?php $activePage = 'auditoria'; $pageTitle = 'Auditoria'; require __DIR__ . '/partials/app-header.php'; ?>
<main class="content-shell"><div class="page-heading"><div><p class="section-kicker">Rastreabilidade</p><h1>Auditoria</h1><p class="muted">Consulte as ações registadas pelo sistema.</p></div></div><form class="audit-filters" method="get" action="auditoria.php"><div><label for="search">Pesquisar</label><input id="search" name="search" value="<?= htmlspecialchars($search, ENT_QUOTES, 'UTF-8') ?>" placeholder="Ação, entidade ou ID"></div><div><label for="user_id">Utilizador</label><select id="user_id" name="user_id"><option value="">Todos</option><?php foreach ($users as $user): ?><option value="<?= (int) $user['id'] ?>" <?= $userId === (int) $user['id'] ? 'selected' : '' ?>><?= htmlspecialchars($user['full_name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div><label for="action">Ação</label><select id="action" name="action"><option value="">Todas</option><?php foreach ($actions as $item): ?><option value="<?= htmlspecialchars($item, ENT_QUOTES, 'UTF-8') ?>" <?= $action === $item ? 'selected' : '' ?>><?= htmlspecialchars($item, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div><label for="entity_type">Entidade</label><select id="entity_type" name="entity_type"><option value="">Todas</option><?php foreach ($entities as $entity): ?><option value="<?= htmlspecialchars($entity, ENT_QUOTES, 'UTF-8') ?>" <?= $entityType === $entity ? 'selected' : '' ?>><?= htmlspecialchars($entity, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div><label for="date_from">De</label><input id="date_from" name="date_from" type="date" value="<?= htmlspecialchars($dateFrom, ENT_QUOTES, 'UTF-8') ?>"></div><div><label for="date_to">Até</label><input id="date_to" name="date_to" type="date" value="<?= htmlspecialchars($dateTo, ENT_QUOTES, 'UTF-8') ?>"></div><button type="submit">Filtrar</button></form><section class="table-panel"><div class="panel-heading"><h2>Eventos registados</h2><span><?= $result['total'] ?> resultado(s)</span></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Utilizador</th><th>Ação</th><th>Entidade</th><th>ID</th><th>Detalhes</th><th>IP</th></tr></thead><tbody><?php foreach ($result['items'] as $event): ?><tr><td><?= htmlspecialchars(date('d/m/Y H:i:s', strtotime($event['created_at'])), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($event['user_name'] ?? 'Sistema/Anónimo', ENT_QUOTES, 'UTF-8') ?><br><span class="table-secondary"><?= htmlspecialchars($event['user_email'] ?? '', ENT_QUOTES, 'UTF-8') ?></span></td><td><span class="audit-action"><?= htmlspecialchars($event['action'], ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars($event['entity_type'], ENT_QUOTES, 'UTF-8') ?></td><td><?= $event['entity_id'] === null ? '-' : (int) $event['entity_id'] ?></td><td><details><summary>Ver detalhes</summary><pre><?= htmlspecialchars(json_encode(['antes' => json_decode($event['old_values'] ?: 'null', true), 'depois' => json_decode($event['new_values'] ?: 'null', true)], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), ENT_QUOTES, 'UTF-8') ?></pre></details></td><td><?= htmlspecialchars($event['ip_address'] ?: '-', ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?><?php if (!$result['items']): ?><tr><td colspan="7" class="empty-state">Nenhum evento encontrado.</td></tr><?php endif; ?></tbody></table></div><?php if ($result['pages'] > 1): ?><nav class="pagination" aria-label="Paginação"><?php for ($number = 1; $number <= $result['pages']; $number++): ?><a class="<?= $number === $page ? 'current' : '' ?>" href="auditoria.php?<?= htmlspecialchars(http_build_query(array_merge($query, ['page' => $number])), ENT_QUOTES, 'UTF-8') ?>"><?= $number ?></a><?php endfor; ?></nav><?php endif; ?></section></main></body></html>